const body = $json.body || $json;
if (!body.discovery_report) {
  throw new Error('CIaC research loop webhook requires discovery_report');
}
return [{ json: { discovery_report: body.discovery_report } }];

const context = $('Retrieve CIaC RAG Context').first().json;
const ollama = $input.first().json;
const raw = String(ollama.response || '').trim();
const trace = `n8n-rag-${Date.now()}`;

function extractJson(text) {
  if (!text) return {};
  try { return JSON.parse(text); } catch (error) {}
  const firstObject = text.indexOf('{');
  const lastObject = text.lastIndexOf('}');
  if (firstObject >= 0 && lastObject > firstObject) {
    try { return JSON.parse(text.slice(firstObject, lastObject + 1)); } catch (error) {}
  }
  const firstArray = text.indexOf('[');
  const lastArray = text.lastIndexOf(']');
  if (firstArray >= 0 && lastArray > firstArray) {
    try { return { candidate_interventions: JSON.parse(text.slice(firstArray, lastArray + 1)) }; } catch (error) {}
  }
  return { parse_error: 'Could not parse Ollama JSON response', raw_response: text.slice(0, 1200) };
}

function safeId(value) {
  return String(value || 'candidate').toLowerCase().replace(/[^a-z0-9_]+/g, '_').replace(/^_+|_+$/g, '') || 'candidate';
}

function normalizeCandidate(candidate, index) {
  const seed = context.seed_candidates?.[index] || context.seed_candidates?.[0] || {};
  const merged = { ...seed, ...candidate };
  const focus = merged.focus_domain || context.focus || 'research';
  const id = safeId(merged.id || `${focus}_ollama_candidate_${index + 1}_v0`);
  const sourceIds = Array.from(new Set([
    ...(merged.rag_context?.source_ids || []),
    ...(context.context_source_ids || []),
    'n8n:workflow:ciac_research_loop_webhook',
    `n8n:trace:${trace}`,
  ].filter(Boolean).map(String)));
  return {
    kind: 'DiscoveryCandidateIntervention',
    version: 'v0',
    id,
    source_loop_id: merged.source_loop_id || context.discovery_report_id || 'unknown_loop',
    focus_domain: focus,
    title: merged.title || `Ollama research candidate ${index + 1}`,
    hypothesis: merged.hypothesis || 'Ollama generated a provisional candidate that requires CIaC validation before promotion.',
    intervention_type: merged.intervention_type || 'research_task',
    target_objects: Array.isArray(merged.target_objects) ? merged.target_objects : [],
    module_refs: Array.isArray(merged.module_refs) ? merged.module_refs : [],
    assumptions: Array.isArray(merged.assumptions) && merged.assumptions.length ? merged.assumptions : [{ id: `assumption_${index + 1}_ollama_local_fit`, statement: 'Generated from local CIaC context and requires human evidence review before promotion.', confidence: 'low', needs_evidence: true }],
    expected_effects: Array.isArray(merged.expected_effects) && merged.expected_effects.length ? merged.expected_effects : [{ metric: 'capability_warning_specificity', direction: 'increase', rationale: 'Candidate should make the weak domain more testable.' }],
    risk_tradeoffs: Array.isArray(merged.risk_tradeoffs) && merged.risk_tradeoffs.length ? merged.risk_tradeoffs : [{ risk: 'Generated proposal may overfit available context.', severity: 'medium', mitigation: 'Run CIaC validation, scenario checks, and human review before promotion.' }],
    simulation_hooks: {
      metrics_to_compare: Array.isArray(merged.simulation_hooks?.metrics_to_compare) ? merged.simulation_hooks.metrics_to_compare : ['capabilities.domain_statuses', 'scenario.blocked_review_domain_count'],
      scenarios_to_run: Array.isArray(merged.simulation_hooks?.scenarios_to_run) ? merged.simulation_hooks.scenarios_to_run : [],
      acceptance_tests: Array.isArray(merged.simulation_hooks?.acceptance_tests) ? merged.simulation_hooks.acceptance_tests : ['No new survival-critical unmet demand is introduced.', 'No labor is shifted into untracked resident burden.'],
    },
    rag_context: {
      queries: Array.isArray(merged.rag_context?.queries) ? merged.rag_context.queries : [`CIaC ${focus} local research context`],
      required_sources: Array.isArray(merged.rag_context?.required_sources) ? merged.rag_context.required_sources : ['patterns/', 'docs/module_reports/', 'schemas/'],
      source_ids: sourceIds,
    },
    status: 'generated',
    provisional: true,
  };
}

const parsed = extractJson(raw);
const modelCandidates = Array.isArray(parsed.candidate_interventions)
  ? parsed.candidate_interventions
  : Array.isArray(parsed.candidates)
    ? parsed.candidates
    : Array.isArray(parsed)
      ? parsed
      : [];
const fallback = context.seed_candidates || [];
const normalized = (modelCandidates.length ? modelCandidates : fallback).slice(0, 3).map(normalizeCandidate);

return [{
  json: {
    kind: 'CIaCResearchLoopResponse',
    version: 'v0',
    source: 'n8n_ollama_rag',
    workflow_name: 'CIaC Research Loop Webhook',
    trace_marker: trace,
    model: ollama.model || 'qwen3.5:9b',
    focus: context.focus,
    discovery_report_id: context.discovery_report_id,
    context_source_ids: context.context_source_ids || [],
    candidate_count: normalized.length,
    candidate_interventions: normalized,
    discovery_brief: {
      summary: parsed.discovery_brief?.summary || parsed.summary || `n8n retrieved ${context.context_source_ids?.length || 0} local source(s), called Ollama, and returned ${normalized.length} generated candidate intervention(s).`,
      model: ollama.model || 'qwen3.5:9b',
      trace_marker: trace,
      context_source_count: context.context_source_ids?.length || 0,
      parse_error: parsed.parse_error || null,
    },
  },
}];
